BEFORE='dbf77646a3f5e1e684226a91bc351e727b53ceeb97f800e9b5eb02209f377faa'
ASSET='a62ee3f5875296a19f06ff3f412f9c7600bc883881f6e2a2ba5a08ea452f8cab'
DATA=''
from pathlib import Path
import base64,hashlib,datetime,shutil,os
root=Path('/var/www/azmednsk-preview')
p=root/'team/index.html'
a=root/'assets/team2-v1/team2-together-smile-20261115.webp'
old=b'/assets/team2-v1/team2-together-1.webp'
new=b'/assets/team2-v1/team2-together-smile-20261115.webp'
sha=lambda b:hashlib.sha256(b).hexdigest()
before=p.read_bytes()
assert sha(before)==BEFORE,'STOP: team page changed'
assert before.count(old)==2,'STOP: unexpected references'
after=before.replace(old,new)
blob=base64.b64decode(DATA)
assert sha(blob)==ASSET,'STOP: asset checksum'
assert not a.exists() or a.read_bytes()==blob,'STOP: asset conflict'
preview=root/'team-2/index.html'
preview_before=preview.read_bytes() if preview.exists() else None
backup=Path('/var/backups/azmednsk')/('team-smile-'+datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ'))
backup.mkdir(parents=True)
shutil.copy2(p,backup/'index.html')
assert p.read_bytes()==before,'STOP: concurrent modification'
a.write_bytes(blob);a.chmod(0o644)
tmp=p.with_name('index.html.smile-tmp')
tmp.write_bytes(after);shutil.copystat(p,tmp);os.replace(tmp,p)
assert p.read_bytes()==after and sha(a.read_bytes())==ASSET
assert preview_before is None or preview.read_bytes()==preview_before
print('TEAM_SMILE=PASS; CHANGE=ONE_GROUP_PHOTO; PREVIEW=UNCHANGED')
print('BACKUP='+str(backup))
print('URL=https://azmednsk.ru/team/')
